// Helper: convert VString to V string
fn vstr_to_string(s C.VString) string {
	if s.str == unsafe { nil } {
		return ''
	}
	return unsafe { cstring_to_vstring(s.str) }
}

// Helper: convert VNode array to []Node
fn c_to_node_array(a C.VArray) []Node {
	mut res := []Node{}
	for i in 0 .. a.len {
		elem_ptr := unsafe { voidptr(byteptr(a.data) + i * a.element_size) }
		res << c_to_node(elem_ptr)
	}
	return res
}

fn c_to_uint64_array(a C.VArray) []u64 {
	mut res := []u64{len: a.len}
	for i in 0 .. a.len {
		res[i] = u64(unsafe { &int(byteptr(a.data))[i] })
	}
	return res
}

fn c_to_integer(c &C.V_Integer) Integer {
	return Integer{
		ival: c.ival
	}
}

fn c_to_float(c &C.V_Float) Float {
	return Float{
		fval: vstr_to_string(c.fval)
	}
}

fn c_to_boolean(c &C.V_Boolean) Boolean {
	return Boolean{
		boolval: c.boolval != 0
	}
}

fn c_to_string(c &C.V_String) String {
	return String{
		sval: vstr_to_string(c.sval)
	}
}

fn c_to_bit_string(c &C.V_BitString) BitString {
	return BitString{
