fn c_to_a_const(c &C.V_AConst) AConst {
	mut result := AConst{
		isnull:   c.isnull != 0
		location: c.location
	}
	result.ival = if c.ival_state == 0 {
		c_to_integer(c.ival_data)
	} else {
		none
	}
	result.fval = if c.fval_state == 0 {
		c_to_float(c.fval_data)
	} else {
		none
	}
	result.boolval = if c.boolval_state == 0 {
		c_to_boolean(c.boolval_data)
	} else {
		none
	}
	result.sval = if c.sval_state == 0 {
		c_to_string(c.sval_data)
	} else {
		none
	}
	result.bsval = if c.bsval_state == 0 {
		c_to_bit_string(c.bsval_data)
	} else {
		none
	}
	return result
}

