fn c_to_select_stmt(c &C.V_SelectStmt) SelectStmt {
	mut result := SelectStmt{
		distinct_clause: c_to_node_array(c.distinct_clause)
		into_clause:     c_to_into_clause(c.into_clause)
		target_list:     c_to_node_array(c.target_list)
		from_clause:     c_to_node_array(c.from_clause)
		where_clause:    c_to_node(voidptr(&c.where_clause))
		group_clause:    c_to_node_array(c.group_clause)
		group_distinct:  c.group_distinct != 0
		having_clause:   c_to_node(voidptr(&c.having_clause))
		window_clause:   c_to_node_array(c.window_clause)
		values_lists:    c_to_node_array(c.values_lists)
		sort_clause:     c_to_node_array(c.sort_clause)
		limit_offset:    c_to_node(voidptr(&c.limit_offset))
		limit_count:     c_to_node(voidptr(&c.limit_count))
		limit_option:    unsafe { LimitOption(c.limit_option) }
		locking_clause:  c_to_node_array(c.locking_clause)
		with_clause:     c_to_with_clause(c.with_clause)
		op:              unsafe { SetOperation(c.op) }
		all:             c.all != 0
		larg:            unsafe { nil }
		rarg:            unsafe { nil }
	}
	if c.larg != unsafe { nil } {
		inner := c_to_select_stmt(unsafe { &C.V_SelectStmt(c.larg) })
		result.larg = unsafe { &inner }
	}
	if c.rarg != unsafe { nil } {
		inner := c_to_select_stmt(unsafe { &C.V_SelectStmt(c.rarg) })
		result.rarg = unsafe { &inner }
	}
	return result
}

