// Node dispatcher: convert VNode (tagged union) to Node sum type
fn c_to_node(vn_ptr voidptr) Node {
	tag := C.pg_query_vnode_tag(vn_ptr)
	if tag == -1 {
		return Alias{}
	}
	if tag == 0 {
		ptr := C.pg_query_vnode_get_Alias(vn_ptr)
		if ptr == unsafe { nil } {
			return Alias{}
		}
		return c_to_alias(unsafe { &C.V_Alias(ptr) })
	}
	if tag == 1 {
		ptr := C.pg_query_vnode_get_RangeVar(vn_ptr)
		return c_to_range_var(unsafe { &C.V_RangeVar(ptr) })
	}
	if tag == 2 {
		ptr := C.pg_query_vnode_get_TableFunc(vn_ptr)
		return c_to_table_func(unsafe { &C.V_TableFunc(ptr) })
	}
	if tag == 3 {
		ptr := C.pg_query_vnode_get_IntoClause(vn_ptr)
		return c_to_into_clause(unsafe { &C.V_IntoClause(ptr) })
	}
	if tag == 4 {
		ptr := C.pg_query_vnode_get_Var(vn_ptr)
		return c_to_var(unsafe { &C.V_Var(ptr) })
	}
	if tag == 5 {
		ptr := C.pg_query_vnode_get_Param(vn_ptr)
		return c_to_param(unsafe { &C.V_Param(ptr) })
	}
	if tag == 6 {
		ptr := C.pg_query_vnode_get_Aggref(vn_ptr)
		return c_to_aggref(unsafe { &C.V_Aggref(ptr) })
	}
	if tag == 7 {
		ptr := C.pg_query_vnode_get_GroupingFunc(vn_ptr)
		return c_to_grouping_func(unsafe { &C.V_GroupingFunc(ptr) })
	}
	if tag == 8 {
		ptr := C.pg_query_vnode_get_WindowFunc(vn_ptr)
		return c_to_window_func(unsafe { &C.V_WindowFunc(ptr) })
	}
	if tag == 9 {
		ptr := C.pg_query_vnode_get_WindowFuncRunCondition(vn_ptr)
		return c_to_window_func_run_condition(unsafe { &C.V_WindowFuncRunCondition(ptr) })
	}
	if tag == 10 {
		ptr := C.pg_query_vnode_get_MergeSupportFunc(vn_ptr)
		return c_to_merge_support_func(unsafe { &C.V_MergeSupportFunc(ptr) })
	}
	if tag == 11 {
		ptr := C.pg_query_vnode_get_SubscriptingRef(vn_ptr)
		return c_to_subscripting_ref(unsafe { &C.V_SubscriptingRef(ptr) })
	}
	if tag == 12 {
		ptr := C.pg_query_vnode_get_FuncExpr(vn_ptr)
		return c_to_func_expr(unsafe { &C.V_FuncExpr(ptr) })
	}
	if tag == 13 {
		ptr := C.pg_query_vnode_get_NamedArgExpr(vn_ptr)
		return c_to_named_arg_expr(unsafe { &C.V_NamedArgExpr(ptr) })
