	}
	if tag == 257 {
		ptr := C.pg_query_vnode_get_AlterSubscriptionStmt(vn_ptr)
		return c_to_alter_subscription_stmt(unsafe { &C.V_AlterSubscriptionStmt(ptr) })
	}
	if tag == 258 {
		ptr := C.pg_query_vnode_get_DropSubscriptionStmt(vn_ptr)
		return c_to_drop_subscription_stmt(unsafe { &C.V_DropSubscriptionStmt(ptr) })
	}
	if tag == 259 {
		ptr := C.pg_query_vnode_get_Integer(vn_ptr)
		return c_to_integer(unsafe { &C.V_Integer(ptr) })
	}
	if tag == 260 {
		ptr := C.pg_query_vnode_get_Float(vn_ptr)
		return c_to_float(unsafe { &C.V_Float(ptr) })
	}
	if tag == 261 {
		ptr := C.pg_query_vnode_get_Boolean(vn_ptr)
		return c_to_boolean(unsafe { &C.V_Boolean(ptr) })
	}
	if tag == 262 {
		ptr := C.pg_query_vnode_get_String(vn_ptr)
		return c_to_string(unsafe { &C.V_String(ptr) })
	}
	if tag == 263 {
		ptr := C.pg_query_vnode_get_BitString(vn_ptr)
		return c_to_bit_string(unsafe { &C.V_BitString(ptr) })
	}
	if tag == 264 {
		ptr := C.pg_query_vnode_get_List(vn_ptr)
		return c_to_list(unsafe { &C.V_List(ptr) })
	}
	if tag == 265 {
		ptr := C.pg_query_vnode_get_IntList(vn_ptr)
		return c_to_int_list(unsafe { &C.V_IntList(ptr) })
	}
	if tag == 266 {
		ptr := C.pg_query_vnode_get_OidList(vn_ptr)
		return c_to_oid_list(unsafe { &C.V_OidList(ptr) })
	}
	if tag == 267 {
		ptr := C.pg_query_vnode_get_AConst(vn_ptr)
		return c_to_a_const(unsafe { &C.V_AConst(ptr) })
	}
	panic('c_to_node: unknown node tag ${tag}')
}

// Parse SQL into typed V AST structs using C bridge + pluck layer.
pub fn parse_ast_direct(input_sql string) !ParseAstResult {
	return parse_ast_direct_opts(input_sql, 0)
}

pub fn parse_ast_direct_opts(input_sql string, parser_options int) !ParseAstResult {
	c_ptr := C.pg_query_bridge_parse_ast_direct(input_sql.str, parser_options)
	if c_ptr == unsafe { nil } {
		return error('parse_ast_direct_opts: C bridge returned nil')
	}
	c_res := unsafe { &C.V_ParseAstResult(c_ptr) }
	defer { C.pg_query_bridge_free_ast_result(c_ptr) }
	mut stmts := []AstRawStmt{}
	for i in 0 .. c_res.stmts.len {
		rs_ptr := unsafe { &C.V_RawStmt(voidptr(byteptr(c_res.stmts.data) +
			i * c_res.stmts.element_size)) }
		stmts << AstRawStmt{
			stmt_location: i64(rs_ptr.stmt_location)
			stmt_len:      i64(rs_ptr.stmt_len)
			stmt:          c_to_node(voidptr(&rs_ptr.stmt))
		}
	}
	return ParseAstResult{
		version: c_res.version
		stmts:   stmts
	}
}
